System.Collections.IEnumerator Verify() {
    var root=MobileGame.Foundation.Editor.Plan020Probe.Root;
    var probe=typeof(MobileGame.Foundation.Editor.Plan020Probe);
    var load=(System.Action<string>)System.Delegate.CreateDelegate(typeof(System.Action<string>),probe.GetMethod("Load",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static));
    var v=UnityEngine.Object.FindFirstObjectByType<MobileGame.Presentation.LaboratoryView>();
    void Write(string name,object value)=>MobileGame.Foundation.Editor.Plan020Probe.Write("../PLAN-021/"+name,value);
    string Fixture(int level)=>System.IO.File.ReadAllText(System.IO.Path.Combine(root,"fixture-"+level+".json"));
    MobileGame.Foundation.Editor.Plan020Probe.Resize(1280,720);
    yield return null;
    var field=typeof(MobileGame.Gameplay.WorkerComponent).GetField("EvaluatedStep",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
    for(int level=0;level<3;level++) {
        for(int repeat=1;repeat<=3;repeat++) {
            load(Fixture(level));v.SetUiPreferences(true,false);
            yield return new UnityEngine.WaitForSecondsRealtime(1);
            var lab=v.Simulation;
            long initial=lab.Map.PathQueries,prev=initial,peak=0;
            MobileGame.Foundation.Editor.Plan020Probe.Measure("../PLAN-021/level"+level+"-run"+repeat);
            while(MobileGame.Foundation.Editor.Plan020Probe.Status.StartsWith("measuring")){
                yield return null;
                long count=lab.Map.PathQueries;peak=System.Math.Max(peak,count-prev);prev=count;
            }
            Write("counts-"+level+"-"+repeat,new{searches=lab.Map.PathQueries-initial,peak,decisions=lab.Decisions});
        }
    }
    load(Fixture(2));v.SetUiPreferences(true,false);
    var sim=v.Simulation;
    double Now()=>UnityEngine.Time.realtimeSinceStartupAsDouble;
    double start=Now(),nextCommand=start+15;
    int minute=0,constructionCount=0;
    long previous=sim.Map.PathQueries,peakFrame=0;
    var rows=new System.Collections.Generic.List<object>();
    var responses=new System.Collections.Generic.List<object>();
    MobileGame.Gameplay.WorkerComponent pending=null;
    long previousDecision=0;
    double issued=0,scheduled=0;
    string kind=null;
    System.Guid siteId=System.Guid.Empty;
    while(Now()-start<1200){
        MobileGame.Presentation.SceneFlowManager.Instance.SendMessage("OnApplicationFocus",true);
        v.SendMessage("OnApplicationFocus",true);
        long count=sim.Map.PathQueries;peakFrame=System.Math.Max(peakFrame,count-previous);previous=count;
        if(pending!=null){
            bool observed=kind=="designate construction" ? System.Linq.Enumerable.Any(sim.Registry.Things,t=>t.TryGetComponent<MobileGame.Gameplay.WorkerComponent>(out var worker) && worker.Job?.TargetId==siteId) : (long)field.GetValue(pending)!=previousDecision;
            if(observed || Now()-issued>2){responses.Add(new{kind,observed,ms=(Now()-issued)*1000,scheduledMs=(Now()-scheduled)*1000});pending=null;}
        }
        if(pending==null && Now()>=nextCommand && Now()-start<1180){
            var idle=System.Linq.Enumerable.FirstOrDefault(sim.Registry.Things,t=>t.TryGetComponent<MobileGame.Gameplay.WorkerComponent>(out var w) && w.Job==null && t.IsPlaced);
            if(idle!=null){
                pending=idle.GetComponent<MobileGame.Gameplay.WorkerComponent>();previousDecision=(long)field.GetValue(pending);scheduled=nextCommand;issued=Now();
                if(constructionCount<2){
                    kind="designate construction";
                    if(!v.BeginStorageConstruction() || !v.PreviewAt(new UnityEngine.Vector2Int(5+constructionCount*5,5)) || !v.ConfirmPlacement())throw new System.Exception("construction probe failed");
                    siteId=System.Linq.Enumerable.Last(System.Linq.Enumerable.OrderBy(sim.Registry.Things,t=>t.CreationOrder)).Id;
                    constructionCount++;
                }else{
                    kind="priority change";
                    if(!v.SetWorkerPriorities(idle.Id,responses.Count%2==0?new[]{2,1,3,4}:new[]{1,2,3,4}))throw new System.Exception("priority probe failed");
                }
                nextCommand=Now()+45;
            }
        }
        if(Now()-start >= (minute+1)*60){
            minute++;sim.ValidateState();rows.Add(new{minute,peakFrame,searches=sim.Map.PathQueries,state=MobileGame.Foundation.Editor.Plan020Probe.Snapshot()});
            Write("soak-progress",new{rows,responses});
        }
        yield return null;
    }
    sim.ValidateState();
    Write("soak-complete",new{wall=Now()-start,game=v.Invasion.Elapsed,peakFrame,rows,responses,state=MobileGame.Foundation.Editor.Plan020Probe.Snapshot()});
}
UnityEngine.Object.FindFirstObjectByType<MobileGame.Presentation.LaboratoryView>().StartCoroutine(Verify());return true;
